/// Where things live. On desktop only `data_dir` is needed; on Android the app
/// passes the bundled Python and QuickJS (native libraries) too.
class EngineConfig {
  final String dataDir;

  /// Android: path of the Python executable (libpython.so).
  final String? python;

  /// Android: PYTHONHOME (the unpacked standard library's parent).
  final String? pythonHome;

  /// Android: QuickJS executable for YouTube's player challenges.
  final String? quickjs;

  /// Android: directory of system certificates.
  final String? caDir;

  /// Use a yt-dlp that is already on this path instead of downloading one.
  final String? ytdlpOverride;

  /// Android: a yt-dlp shipped inside the app, used only if downloading one fails.
  final String? bundledYtdlp;

  const EngineConfig({
    required this.dataDir,
    this.python,
    this.pythonHome,
    this.quickjs,
    this.caDir,
    this.ytdlpOverride,
    this.bundledYtdlp,
  });

  @override
  int get hashCode =>
      dataDir.hashCode ^
      python.hashCode ^
      pythonHome.hashCode ^
      quickjs.hashCode ^
      caDir.hashCode ^
      ytdlpOverride.hashCode ^
      bundledYtdlp.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is EngineConfig &&
          runtimeType == other.runtimeType &&
          dataDir == other.dataDir &&
          python == other.python &&
          pythonHome == other.pythonHome &&
          quickjs == other.quickjs &&
          caDir == other.caDir &&
          ytdlpOverride == other.ytdlpOverride &&
          bundledYtdlp == other.bundledYtdlp;
}

